create table public.ns_profiles(user_id uuid primary key references auth.users(id) on delete cascade, display_name text not null check(char_length(display_name) between 1 and 100), onboarded boolean not null default false);
create table public.ns_households(id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, name text not null check(char_length(name) between 1 and 100));
create table public.ns_state(user_id uuid primary key references auth.users(id) on delete cascade, theme text not null check(theme in ('midnight','light')), modules jsonb not null check(jsonb_typeof(modules)='array'), notes jsonb not null check(jsonb_typeof(notes)='array'), revision bigint not null default 0);
alter table public.ns_profiles enable row level security; revoke all on public.ns_profiles from anon, authenticated; grant select,insert,update on public.ns_profiles to authenticated; create policy own_select on public.ns_profiles for select to authenticated using ((select auth.uid())=user_id); create policy own_insert on public.ns_profiles for insert to authenticated with check ((select auth.uid())=user_id); create policy own_update on public.ns_profiles for update to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
alter table public.ns_households enable row level security; revoke all on public.ns_households from anon, authenticated; grant select,insert,update on public.ns_households to authenticated; create policy own_select on public.ns_households for select to authenticated using ((select auth.uid())=owner_id); create policy own_insert on public.ns_households for insert to authenticated with check ((select auth.uid())=owner_id); create policy own_update on public.ns_households for update to authenticated using ((select auth.uid())=owner_id) with check ((select auth.uid())=owner_id);
alter table public.ns_state enable row level security; revoke all on public.ns_state from anon, authenticated; grant select,insert,update on public.ns_state to authenticated; create policy own_select on public.ns_state for select to authenticated using ((select auth.uid())=user_id); create policy own_insert on public.ns_state for insert to authenticated with check ((select auth.uid())=user_id); create policy own_update on public.ns_state for update to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create index ns_households_owner_idx on public.ns_households(owner_id);